    {
      "id": 1,
      "claim": "An uncontrollable factor is a variable that influences the dependent variable but cannot be manipulated by the students during the investigation.",
      "evidence": "Standard definition of uncontrolled/confounding variables in experimental design.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The dependent variable in the investigation is the amount of electricity used, reflected in the November electric bill (compared to October).",
      "evidence": "Problem statement: students compare their October bill to the one they would receive for November.",
      "weight": 0.10,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Outdoor temperature in November is a weather condition that students cannot control and that directly changes heating/cooling electricity demand.",
      "evidence": "Temperature varies independently of human actions and is a primary driver of residential electricity consumption.",
      "weight": 0.30,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "The other options are either controllable (the list of tips, the investigation time) or essentially constant and not a source of variable change (bill accuracy).",
      "evidence": "Students choose and follow the tips; the teacher sets the time frame; billing accuracy is a systematic property that does not fluctuate day‑to‑day.",
      "weight": 0.25,
      "depends_on": [1, 2]
    },
    {
      "id": 5,
      "claim": "Because temperature is both uncontrollable and the factor that most strongly and variably affects electricity use, it is the most uncontrollable factor in the investigation.",
      "evidence": "Among uncontrollable variables, only temperature introduces significant, unpredictable variation that can mask the effect of the energy‑saving tips.",
      "weight": 0.15,
      "depends_on": [3, 4]
    }
  ],
